create or replace function public.ahrefs_due_domains(p_limit integer, p_tier smallint) returns table (id uuid, domain text, tier smallint) language sql volatile security definer set search_path = public as $$ with settings as (select * from public.refresh_settings where id) select w.id, w.domain, coalesce(w.ahrefs_tier, 3)::smallint as tier from public.websites w cross join settings s where w.status <> 'archived' and (p_tier is null or coalesce(w.ahrefs_tier, 3) = p_tier) and ( w.last_ahrefs_refresh_at is null or w.last_ahrefs_refresh_at < timezone('utc', now()) - make_interval( days => case coalesce(w.ahrefs_tier, 3) when 1 then s.tier1_interval_days when 2 then s.tier2_interval_days else s.tier3_interval_days end ) ) order by coalesce(w.ahrefs_tier, 3), w.last_ahrefs_refresh_at nulls first, w.id limit greatest(0, p_limit); $$;
revoke all on function public.ahrefs_due_domains(integer, smallint) from public;
